<span class="line"><span style="--shiki-light:#268BD2;--shiki-dark:#268BD2;">  oauth</span><span style="--shiki-light:#657B83;--shiki-dark:#839496;">:                           </span><span style="--shiki-light:#93A1A1;--shiki-light-font-style:italic;--shiki-dark:#586E75;--shiki-dark-font-style:italic;"># Optional: enables user auth</span></span>
